(2895375, 403295, 36619, '<td valign="top">great scene, love the rustic feel&amp; i really like the ominous sky!!</td>', 'great scene, love the rustic feel& i really like the ominous sky!!', '2006-10-04 11:08:45.000000', NULL, 1),
(2895379, 404647, 36619, '<td valign="top">the contrast here really make the image POP!! fantastic job!</td>', 'the contrast here really make the image POP!! fantastic job!', '2006-10-04 11:10:08.000000', NULL, 1),
(2895391, 405509, 3102, '<td valign="top">Whoa.  I guess it''s high contrast, but yeesh, that doesn''t imply "completely blown out" to the point where you can''t see the face any more.  This looks like one of my very first pictures I ever took when I was a kid in the 70s.</td>', 'Whoa.  I guess it''s high contrast, but yeesh, that doesn''t imply "completely blown out" to the point where you can''t see the face any more.  This looks like one of my very first pictures I ever took when I was a kid in the 70s.', '2006-10-04 11:14:17.000000', NULL, 1),
(2895422, 404985, 1662, '<td valign="top">A slant to the leaf might have been a little more interesting, but good idea and nice photo!</td>', 'A slant to the leaf might have been a little more interesting, but good idea and nice photo!', '2006-10-04 11:21:22.000000', NULL, 1),
(2895425, 404968, 3102, '<td valign="top">A nice shot, but doesn''t seem to be high contrast to me.  If anything, it has less contrast than the normal shot.</td>', 'A nice shot, but doesn''t seem to be high contrast to me.  If anything, it has less contrast than the normal shot.', '2006-10-04 11:22:01.000000', NULL, 1),
(2895440, 403759, 61559, '<td valign="top">Awesome idea! The composition would really benefit from having the entire base of the tall glass in the photo though.</td>', 'Awesome idea! The composition would really benefit from having the entire base of the tall glass in the photo though.', '2006-10-04 11:27:08.000000', NULL, 1),
(2895444, 405916, 9504, '<td valign="top">Cute poodle, but the texture is a bit distracting for me -- even if it is all natural.</td>', 'Cute poodle, but the texture is a bit distracting for me -- even if it is all natural.', '2006-10-04 11:28:09.000000', NULL, 1),
(2895445, 403658, 1662, '<td valign="top">The kid gets lost in the picture, thus wouldn''t have made it a part of the title, but cool photo! I love the wall.</td>', 'The kid gets lost in the picture, thus wouldn''t have made it a part of the title, but cool photo! I love the wall.', '2006-10-04 11:28:20.000000', NULL, 1),
