(2895455, 405954, 1662, '<td valign="top">Great idea and great shot. I like the angle.</td>', 'Great idea and great shot. I like the angle.', '2006-10-04 11:29:41.000000', NULL, 1),
(2895471, 406014, 15711, '<td valign="top">Great example of the challenge criteria.  Mostly highlights and shadows with minimal mid tones. I''d use this as an example!! I like it.</td>', 'Great example of the challenge criteria.  Mostly highlights and shadows with minimal mid tones. I''d use this as an example!! I like it.', '2006-10-04 11:32:26.000000', NULL, 1),
