(2896814, 405922, 14010, '<td valign="top">Oh! If it wasn''t for that frame!</td>', 'Oh! If it wasn''t for that frame!', '2006-10-04 18:20:28.000000', NULL, 1),
(2896818, 404834, 65319, '<td valign="top">Stunning colors.  I would have given this photograph an extra point if I could see more of it.  The dimensions can be as big as 640.  6</td>', 'Stunning colors.  I would have given this photograph an extra point if I could see more of it.  The dimensions can be as big as 640.  6', '2006-10-04 18:21:08.000000', NULL, 1),
