(2896987, 404899, 64446, '<td valign="top">Hands too much saturation IMO.</td>', 'Hands too much saturation IMO.', '2006-10-04 19:15:32.000000', NULL, 1),
(2896988, 405442, 64446, '<td valign="top">It''s a nice composition and well executed, but this kind of subject is becoming a common place IMHO.</td>', 'It''s a nice composition and well executed, but this kind of subject is becoming a common place IMHO.', '2006-10-04 19:15:36.000000', NULL, 1),
(2896989, 402988, 56417, '<td valign="top">nice</td>', 'nice', '2006-10-04 19:15:47.000000', NULL, 1),
