(2897011, 405730, 65319, '<td valign="top">The concept is thoughtful and I can''t help but wonder if the model could be changed to an older person at the end of life perhaps with a cane crossing the threshold into.... 7.</td>', 'The concept is thoughtful and I can''t help but wonder if the model could be changed to an older person at the end of life perhaps with a cane crossing the threshold into.... 7.', '2006-10-04 19:22:12.000000', NULL, 1),
(2897021, 405155, 65319, '<td valign="top">What''s striking about this photo is the clarity of detail and the character lines in this man''s face.  Too bad the eyes are in shadow which would bring out the essentials of the model''s face even more.  6.</td>', 'What''s striking about this photo is the clarity of detail and the character lines in this man''s face.  Too bad the eyes are in shadow which would bring out the essentials of the model''s face even more.  6.', '2006-10-04 19:24:31.000000', NULL, 1),
(2897027, 406025, 64446, '<td valign="top">I can se the mask and the eyem but I can''t identify everything else... All I see is a big shadow.</td>', 'I can se the mask and the eyem but I can''t identify everything else... All I see is a big shadow.', '2006-10-04 19:25:55.000000', NULL, 1),
(2897030, 405134, 65319, '<td valign="top">A photo full of wonderful texture!  6</td>', 'A photo full of wonderful texture!  6', '2006-10-04 19:26:34.000000', NULL, 1),
