(2897167, 404870, 27935, '<td valign="top">tighter crop? longer depth of field?  Nice contrast, great idea!</td>', 'tighter crop? longer depth of field?  Nice contrast, great idea!', '2006-10-04 20:13:12.000000', NULL, 1),
(2897178, 404353, 27935, '<td valign="top">sweet title!</td>', 'sweet title!', '2006-10-04 20:16:01.000000', NULL, 1),
