(2897190, 403191, 27935, '<td valign="top">great angle, great setup, great saturation!  just a little more detail in the yellow i.e. a little less yellow brightness would nail it!</td>', 'great angle, great setup, great saturation!  just a little more detail in the yellow i.e. a little less yellow brightness would nail it!', '2006-10-04 20:20:30.000000', NULL, 1),
