(2899361, 405512, 65592, '<td valign="top">A little bit overexposed imo, but it is a great shot.</td>', 'A little bit overexposed imo, but it is a great shot.', '2006-10-05 10:22:26.000000', NULL, 1),
(2899378, 402336, 65592, '<td valign="top">Finally a great "colored" portrait. I suppose that many comenters will tell you that it would be better a b/w portrait. Not me.</td>', 'Finally a great "colored" portrait. I suppose that many comenters will tell you that it would be better a b/w portrait. Not me.', '2006-10-05 10:28:34.000000', NULL, 1),
(2899395, 405978, 65592, '<td valign="top">I would prefer a little less negative space but that way it gives the viewer the feeling of a long fall. Great shot.</td>', 'I would prefer a little less negative space but that way it gives the viewer the feeling of a long fall. Great shot.', '2006-10-05 10:35:50.000000', NULL, 1),
(2899452, 405301, 47316, '<td valign="top">I think the contrast is too blown out.  Shouldn''t be losing the details so much, like in her fingers, eyebrows and hair.<br/> <br/>Pretty eyes, I''d like to see the original of this.</td>', 'I think the contrast is too blown out.  Shouldn''t be losing the details so much, like in her fingers, eyebrows and hair. Pretty eyes, I''d like to see the original of this.', '2006-10-05 11:04:34.000000', NULL, 1),
(2899459, 402762, 47316, '<td valign="top">Interesting angle and use of lines. Not sure how much you changed in editing but I think the contrast could be higher because your darkest shade is in the back from the tree and I think something more in the foreground should be darker.</td>', 'Interesting angle and use of lines. Not sure how much you changed in editing but I think the contrast could be higher because your darkest shade is in the back from the tree and I think something more in the foreground should be darker.', '2006-10-05 11:06:25.000000', NULL, 1),
(2899464, 403376, 47316, '<td valign="top">Interesting photograph. For me I think it would have more impact if she were looking at the camera, or at least more to the side instead of up.</td>', 'Interesting photograph. For me I think it would have more impact if she were looking at the camera, or at least more to the side instead of up.', '2006-10-05 11:08:23.000000', NULL, 1),
(2899468, 402663, 47316, '<td valign="top">Beautiful shot. Love the long cropping.</td>', 'Beautiful shot. Love the long cropping.', '2006-10-05 11:09:12.000000', NULL, 1),
(2899474, 405811, 47316, '<td valign="top">Beautiful! I wish I could see trees like that around here! Not so sure if the composition does the scene justice.</td>', 'Beautiful! I wish I could see trees like that around here! Not so sure if the composition does the scene justice.', '2006-10-05 11:10:36.000000', NULL, 1),
(2899477, 403746, 47316, '<td valign="top">Ahhh infrared. LOL. Before I read the title I was staring at the photo for the longest time wondering about how you could photoshop those colors in basic.<br/> <br/>Beautiful shot. Love the composition. Makes me think of being in Narnia. :)</td>', 'Ahhh infrared. LOL. Before I read the title I was staring at the photo for the longest time wondering about how you could photoshop those colors in basic. Beautiful shot. Love the composition. Makes me think of being in Narnia. :)', '2006-10-05 11:11:46.000000', NULL, 1),
(2899501, 405612, 38509, '<td valign="top">nice, great contrast ... and the frame is okay !</td>', 'nice, great contrast ... and the frame is okay !', '2006-10-05 11:19:24.000000', NULL, 1),
(2899532, 404882, 51900, '<td valign="top">props for actually shooting something, instead of buying flowers</td>', 'props for actually shooting something, instead of buying flowers', '2006-10-05 11:31:20.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2899568, 404406, 6388, '<td valign="top">easy.  although it was on page 4 so it took me a few minutes :)</td>', 'easy.  although it was on page 4 so it took me a few minutes :)', '2006-10-05 11:52:21.000000', NULL, 1),
(2899657, 402663, 5354, '<td valign="top">suffers because of the panorama crop making the height small. Would be really great in a bigger size.</td>', 'suffers because of the panorama crop making the height small. Would be really great in a bigger size.', '2006-10-05 12:34:20.000000', NULL, 1),
(2899662, 403476, 5354, '<td valign="top">Just needs someone in the shot - maybe a commuter or a shopper down the bottom.</td>', 'Just needs someone in the shot - maybe a commuter or a shopper down the bottom.', '2006-10-05 12:40:18.000000', NULL, 1),
(2899691, 405904, 5354, '<td valign="top">Focus appears to have gone soft on the nose.</td>', 'Focus appears to have gone soft on the nose.', '2006-10-05 12:52:20.000000', NULL, 1),
(2899698, 405719, 5354, '<td valign="top">Simple and effective. I like it, one of may favourites of the challenge</td>', 'Simple and effective. I like it, one of may favourites of the challenge', '2006-10-05 12:53:59.000000', NULL, 1),
(2899707, 404968, 5354, '<td valign="top">Hi-key yes, high contrast no, which is a shame.</td>', 'Hi-key yes, high contrast no, which is a shame.', '2006-10-05 12:57:18.000000', NULL, 1),
(2899763, 403889, 59256, '<td valign="top">JAMES GARDEN? RIGHT</td>', 'JAMES GARDEN? RIGHT', '2006-10-05 13:13:03.000000', NULL, 1),
(2899822, 402590, 66193, '<td valign="top">I think this might have worked better if you had gotten closer to the broken door.  Then you could have concentrated on the interesting lines there, and also eliminate the very bright sky.  Having the sky there limited your ability to expand the tonal range in the shed, resulting in a muted range there. Unless of course you totally blew out the highlights in the sky</td>', 'I think this might have worked better if you had gotten closer to the broken door.  Then you could have concentrated on the interesting lines there, and also eliminate the very bright sky.  Having the sky there limited your ability to expand the tonal range in the shed, resulting in a muted range there. Unless of course you totally blew out the highlights in the sky', '2006-10-05 13:28:03.000000', NULL, 1),
(2899823, 404487, 66193, '<td valign="top">a little OOF</td>', 'a little OOF', '2006-10-05 13:28:30.000000', NULL, 1),
(2899824, 403646, 66193, '<td valign="top">nice idea and treatment.  An off-center composition would have helped, though.</td>', 'nice idea and treatment.  An off-center composition would have helped, though.', '2006-10-05 13:29:04.000000', NULL, 1),
(2899874, 405667, 34857, '<td valign="top">beautiful eyes. A gaze that penetrates walls.</td>', 'beautiful eyes. A gaze that penetrates walls.', '2006-10-05 13:50:04.000000', NULL, 1),
(2899882, 405965, 34857, '<td valign="top">Loving the texture that you captured on the rear wall.</td>', 'Loving the texture that you captured on the rear wall.', '2006-10-05 13:57:06.000000', NULL, 1),
(2899884, 404390, 34857, '<td valign="top">Hard to rate this one. I am definitely digging  th econtrast between the road and the runners, but the runners could use more highlights to really make this one stand out... Nice overall.</td>', 'Hard to rate this one. I am definitely digging  th econtrast between the road and the runners, but the runners could use more highlights to really make this one stand out... Nice overall.', '2006-10-05 13:58:41.000000', NULL, 1),
(2899888, 404245, 34857, '<td valign="top">So good it sends chills down my spine. Its like his touch lights up the entire scene. Lovely DOF, excellent composure... Simply lovely.</td>', 'So good it sends chills down my spine. Its like his touch lights up the entire scene. Lovely DOF, excellent composure... Simply lovely.', '2006-10-05 14:02:36.000000', NULL, 1),
(2899890, 403362, 34857, '<td valign="top">A little to bleach out of the left side, nut not bad.</td>', 'A little to bleach out of the left side, nut not bad.', '2006-10-05 14:03:11.000000', NULL, 1),
(2899892, 405879, 34857, '<td valign="top">Beautiful!! The expression, compliment with that hair/eyes, very nice.</td>', 'Beautiful!! The expression, compliment with that hair/eyes, very nice.', '2006-10-05 14:03:59.000000', NULL, 1),
(2899893, 406014, 34857, '<td valign="top">Loving the quality on this one. Very nice.</td>', 'Loving the quality on this one. Very nice.', '2006-10-05 14:04:33.000000', NULL, 1),
