(2902743, 405791, 66490, '<td valign="top">The foreground is hard to distinguish. It seems washed out by the sunlight.</td>', 'The foreground is hard to distinguish. It seems washed out by the sunlight.', '2006-10-06 11:46:19.000000', NULL, 1),
(2902745, 406046, 66490, '<td valign="top">A bit of an odd angle. The face has got a slight blur to it.</td>', 'A bit of an odd angle. The face has got a slight blur to it.', '2006-10-06 11:46:52.000000', NULL, 1),
(2902761, 402592, 66490, '<td valign="top">One flock doesn''t scream out Exodus to me. If there were a lot more to it - or even zoomed it maybe.</td>', 'One flock doesn''t scream out Exodus to me. If there were a lot more to it - or even zoomed it maybe.', '2006-10-06 11:50:09.000000', NULL, 1),
(2902766, 404949, 66490, '<td valign="top">Interesting pose - i was thinking that it was something I had seen before - but I like how it''s only the eye. None of the nose or anything, it let''s the skin of the face and arm blend together.</td>', 'Interesting pose - i was thinking that it was something I had seen before - but I like how it''s only the eye. None of the nose or anything, it let''s the skin of the face and arm blend together.', '2006-10-06 11:51:24.000000', NULL, 1),
(2902769, 404161, 66490, '<td valign="top">Love the muted colors!</td>', 'Love the muted colors!', '2006-10-06 11:51:36.000000', NULL, 1),
(2902772, 405946, 66490, '<td valign="top">Great expression!</td>', 'Great expression!', '2006-10-06 11:51:51.000000', NULL, 1),
(2902778, 405879, 66490, '<td valign="top">That''s a gorgeous hair color! Especially against the green.</td>', 'That''s a gorgeous hair color! Especially against the green.', '2006-10-06 11:53:27.000000', NULL, 1),
(2902780, 404595, 66490, '<td valign="top">There''s too much dead space in the upper right corner.</td>', 'There''s too much dead space in the upper right corner.', '2006-10-06 11:53:51.000000', NULL, 1),
(2902784, 405872, 66490, '<td valign="top">Maybe up the contrast a tiny bit more so those blacks stand out even better.</td>', 'Maybe up the contrast a tiny bit more so those blacks stand out even better.', '2006-10-06 11:54:39.000000', NULL, 1),
(2902789, 405905, 66490, '<td valign="top">I like how you have a longer canvas - it really helps the idea of the cat chasing something, but it''s just out of our view....</td>', 'I like how you have a longer canvas - it really helps the idea of the cat chasing something, but it''s just out of our view....', '2006-10-06 11:55:26.000000', NULL, 1),
(2902791, 403281, 66490, '<td valign="top">Not enough balance for me. It''s over too much to the right.</td>', 'Not enough balance for me. It''s over too much to the right.', '2006-10-06 11:55:52.000000', NULL, 1),
(2902794, 404891, 66490, '<td valign="top">It''d be cool if this was contrasting with something other than color - like a fancy car, or something nice looking in this place. So it doesn''t belong.</td>', 'It''d be cool if this was contrasting with something other than color - like a fancy car, or something nice looking in this place. So it doesn''t belong.', '2006-10-06 11:56:34.000000', NULL, 1),
(2902799, 402450, 66490, '<td valign="top">What the heck is in the mouth???</td>', 'What the heck is in the mouth???', '2006-10-06 11:57:14.000000', NULL, 1),
