(2902813, 405708, 66490, '<td valign="top">The border distracts me....this kind of emotion is more raw that the whole image should seem so.</td>', 'The border distracts me....this kind of emotion is more raw that the whole image should seem so.', '2006-10-06 12:02:16.000000', NULL, 1),
(2902815, 403709, 66490, '<td valign="top">A curse on owls - one of those bastards took out my windshield on Christmas Eve. I hate it that they are beautiful. I could almost see this more vertical witht the owl coming off the side.</td>', 'A curse on owls - one of those bastards took out my windshield on Christmas Eve. I hate it that they are beautiful. I could almost see this more vertical witht the owl coming off the side.', '2006-10-06 12:03:14.000000', NULL, 1),
(2902817, 405515, 66490, '<td valign="top">Ohhh...nice with the wording, that''s a great thing to leave hanging! What does the rest say, who is it talking about. Very cool.</td>', 'Ohhh...nice with the wording, that''s a great thing to leave hanging! What does the rest say, who is it talking about. Very cool.', '2006-10-06 12:04:05.000000', NULL, 1),
(2902819, 403746, 66490, '<td valign="top">Whoa.</td>', 'Whoa.', '2006-10-06 12:04:25.000000', NULL, 1),
(2902820, 402965, 66490, '<td valign="top">Gritty. Especially with that detailed ground to it.</td>', 'Gritty. Especially with that detailed ground to it.', '2006-10-06 12:05:03.000000', NULL, 1),
(2902821, 403413, 66490, '<td valign="top">hard to understand this image.</td>', 'hard to understand this image.', '2006-10-06 12:05:21.000000', NULL, 1),
(2902823, 405699, 66490, '<td valign="top">More clouds to help with idea!</td>', 'More clouds to help with idea!', '2006-10-06 12:05:38.000000', NULL, 1),
(2902826, 405848, 66490, '<td valign="top">Peaceful. Interesting. Especially that slight orange with the green.</td>', 'Peaceful. Interesting. Especially that slight orange with the green.', '2006-10-06 12:06:08.000000', NULL, 1),
