INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2902849, 404792, 66490, '<td valign="top">What''s going on in the foreground there? Nice contrast</td>', 'What''s going on in the foreground there? Nice contrast', '2006-10-06 12:16:10.000000', NULL, 1),
(2902850, 405315, 66490, '<td valign="top">A little creepy....but cool. I think those eyes get me the most.</td>', 'A little creepy....but cool. I think those eyes get me the most.', '2006-10-06 12:16:35.000000', NULL, 1),
(2902852, 405641, 66490, '<td valign="top">What''s uncertain? Good blk &amp; wht - nice blurring and focus on the guy</td>', 'What''s uncertain? Good blk & wht - nice blurring and focus on the guy', '2006-10-06 12:17:16.000000', NULL, 1),
(2902855, 404117, 66490, '<td valign="top">That ever so slight blur always pisses me off when I try to photograph my dog.</td>', 'That ever so slight blur always pisses me off when I try to photograph my dog.', '2006-10-06 12:17:47.000000', NULL, 1),
(2902858, 405252, 66490, '<td valign="top">But then focus on the street light. It''s all the way on the side!</td>', 'But then focus on the street light. It''s all the way on the side!', '2006-10-06 12:18:20.000000', NULL, 1),
(2902859, 406000, 66490, '<td valign="top">I love the faint violet tone to it....</td>', 'I love the faint violet tone to it....', '2006-10-06 12:19:08.000000', NULL, 1),
(2902863, 405499, 66490, '<td valign="top">I see what you''re trying to get at, but I don''t really think it''s quite there.</td>', 'I see what you''re trying to get at, but I don''t really think it''s quite there.', '2006-10-06 12:19:47.000000', NULL, 1),
(2902866, 405422, 66490, '<td valign="top">Good balance</td>', 'Good balance', '2006-10-06 12:20:09.000000', NULL, 1),
