INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2910689, 403104, 52854, '<td valign="top">This is an interesting photo but for me, very unclear. My first distraction is the bottom front - second is the black tree. Nothing is crisp or in focus. There''s good stuff going on but not working together. I hope this comment is taken as it is intended - in a helpful way.</td>', 'This is an interesting photo but for me, very unclear. My first distraction is the bottom front - second is the black tree. Nothing is crisp or in focus. There''s good stuff going on but not working together. I hope this comment is taken as it is intended - in a helpful way.', '2006-10-09 10:25:34.000000', NULL, 1),
(2910702, 404935, 52854, '<td valign="top">Nice photo!</td>', 'Nice photo!', '2006-10-09 10:27:40.000000', NULL, 1),
(2910719, 405793, 52854, '<td valign="top">Great idea but not high really contrast and the hay bales are undefinable.</td>', 'Great idea but not high really contrast and the hay bales are undefinable.', '2006-10-09 10:32:41.000000', NULL, 1),
(2910730, 405740, 52854, '<td valign="top">Nice photo -</td>', 'Nice photo -', '2006-10-09 10:36:24.000000', NULL, 1),
