(2911157, 405644, 50695, '<td valign="top">The concept is highly poetic and the execution is elegant. 8</td>', 'The concept is highly poetic and the execution is elegant. 8', '2006-10-09 12:08:00.000000', NULL, 1),
(2911160, 405442, 50695, '<td valign="top">I''m not sure why, but I find this so much more compelling than other ferris wheel shots. The wheel has a real personality and heft to it. 8</td>', 'I''m not sure why, but I find this so much more compelling than other ferris wheel shots. The wheel has a real personality and heft to it. 8', '2006-10-09 12:08:37.000000', NULL, 1),
(2911162, 404016, 50695, '<td valign="top">fascinating milieu. 8</td>', 'fascinating milieu. 8', '2006-10-09 12:08:51.000000', NULL, 1),
