(2912934, 405892, 50695, '<td valign="top">Looks like flesh peeking through, which makes the picture much more interesting in its mystery. 7</td>', 'Looks like flesh peeking through, which makes the picture much more interesting in its mystery. 7', '2006-10-09 23:44:12.000000', NULL, 1),
(2912936, 405708, 20324, '<td valign="top">Very nice portrait! Soft but crispy at the same time. 10</td>', 'Very nice portrait! Soft but crispy at the same time. 10', '2006-10-09 23:44:46.000000', NULL, 1),
(2912937, 406026, 50695, '<td valign="top">this is as high contrast as it gets, but you still maintain representation. I just wish the subject were a little more interesting. 7</td>', 'this is as high contrast as it gets, but you still maintain representation. I just wish the subject were a little more interesting. 7', '2006-10-09 23:44:57.000000', NULL, 1),
