(2914210, 402482, 49326, '<td valign="top">Is that Krisby? :)<br/> <br/>Mér finnst myndin svolítið flöt, það er að segja það eru fáir tónar í henni og það er svolítið mikið af þessum gula tóni.</td>', 'Is that Krisby? :) Mér finnst myndin svolítið flöt, það er að segja það eru fáir tónar í henni og það er svolítið mikið af þessum gula tóni.', '2006-10-10 13:05:58.000000', NULL, 1),
(2914213, 403746, 49326, '<td valign="top">Good use of infrared.</td>', 'Good use of infrared.', '2006-10-10 13:06:59.000000', NULL, 1),
(2914214, 405667, 49326, '<td valign="top">Wow, that''s scary.</td>', 'Wow, that''s scary.', '2006-10-10 13:07:31.000000', NULL, 1),
(2914218, 405509, 49326, '<td valign="top">It might just be me, but I think it is pretty interesting. I don''t know why. Maybe because it''s so different.</td>', 'It might just be me, but I think it is pretty interesting. I don''t know why. Maybe because it''s so different.', '2006-10-10 13:09:27.000000', NULL, 1),
