(2914380, 403161, 64434, '<td valign="top">i''d really like to see it bigger</td>', 'i''d really like to see it bigger', '2006-10-10 14:41:59.000000', NULL, 1),
(2914389, 405667, 61191, '<td valign="top">Very low-key but interesting. I like it.</td>', 'Very low-key but interesting. I like it.', '2006-10-10 14:45:16.000000', NULL, 1),
(2914392, 405811, 61191, '<td valign="top">Great fall colors!</td>', 'Great fall colors!', '2006-10-10 14:46:36.000000', NULL, 1),
(2914396, 405796, 59215, '<td valign="top">Beautiful silhouette. The blades look very detailed and delicate against the bright sky- which also had some nice detail in the clouds. The jet contrail in the sky on the left is disctracing, would suggest cropping it out.</td>', 'Beautiful silhouette. The blades look very detailed and delicate against the bright sky- which also had some nice detail in the clouds. The jet contrail in the sky on the left is disctracing, would suggest cropping it out.', '2006-10-10 14:47:29.000000', NULL, 1),
(2914402, 405492, 61191, '<td valign="top">Great textures on the wall. Lighting is cool!</td>', 'Great textures on the wall. Lighting is cool!', '2006-10-10 14:49:40.000000', NULL, 1),
(2914404, 404406, 61191, '<td valign="top">Amazing portrait, stunning eyes. Love the details.</td>', 'Amazing portrait, stunning eyes. Love the details.', '2006-10-10 14:50:12.000000', NULL, 1),
(2914446, 405922, 61191, '<td valign="top">Your shot is great. If only you''d left out the frame...</td>', 'Your shot is great. If only you''d left out the frame...', '2006-10-10 15:01:56.000000', NULL, 1),
(2914452, 402592, 61191, '<td valign="top">Great colors! The birds add depth to this image.</td>', 'Great colors! The birds add depth to this image.', '2006-10-10 15:03:13.000000', NULL, 1),
(2914467, 403789, 61191, '<td valign="top">The lime is out of focus thus it lacks detail. And detail is a must when you do shots based on simplicity like this. I like your idea, better luck next time!</td>', 'The lime is out of focus thus it lacks detail. And detail is a must when you do shots based on simplicity like this. I like your idea, better luck next time!', '2006-10-10 15:12:05.000000', NULL, 1),
(2914528, 405515, 56730, '<td valign="top">Interesting shot</td>', 'Interesting shot', '2006-10-10 15:46:48.000000', NULL, 1),
(2914531, 404829, 56730, '<td valign="top">Very nice pic...love the lighting</td>', 'Very nice pic...love the lighting', '2006-10-10 15:47:59.000000', NULL, 1),
(2914549, 404808, 56730, '<td valign="top">Like the composition and lighting, nice job</td>', 'Like the composition and lighting, nice job', '2006-10-10 15:53:42.000000', NULL, 1),
